import { useIntl } from 'react-intl';

import {
  PageHeader,
  PillarResources,
  StickyScrollWithFilters,
} from 'components';
import {
  StyledGridContainer,
  StyledHomeContainer,
  StyledHomeHeaderContainer,
} from 'shared/Styles/layout.styles';

import { CONNECTIONS_CREATIVITY_HOME_PAGE_NAME } from '../../constants';
import type { ConnectionsCreativityHomePageDataBundle } from '../../hooks';
import { HowWeDoIt } from '../HowWeDoIt/HowWeDoIt';
import { PerformanceKpiSection } from '../PerformanceKpiSection/PerformanceKpiSection';

export interface ConnectionsCreativityHomeContentProps extends ConnectionsCreativityHomePageDataBundle {
  isContentEnabled: boolean;
}

export const ConnectionsCreativityHomeContent = ({
  isContentEnabled,
  isDesktopLarge,
  pageData,
  mainCardsData,
  resourceAllocationCardsData,
  onSparklineCardClick,
  onResourceAllocationCardClick,
}: ConnectionsCreativityHomeContentProps) => {
  const { formatMessage } = useIntl();

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: CONNECTIONS_CREATIVITY_HOME_PAGE_NAME,
          visibleFields: ['zone', 'country', 'periods'],
          hidden: !isContentEnabled,
        }}
        breadcrumbs={{
          pageList: [
            {
              href: '/connections-creativity',
              pageName: formatMessage({
                id: 'ConnectionsCreativity.Home.breadcrumbPageName',
              }),
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
      />

      <StyledGridContainer $isResponsivePage>
        <StyledHomeContainer>
          <StyledHomeHeaderContainer>
            <PageHeader
              title={formatMessage({
                id: 'Pillars.sidebar.connectionsCreativity',
              })}
              subtitle={formatMessage({
                id: 'ConnectionsCreativity.Home.pageSubtitle',
              })}
            />
          </StyledHomeHeaderContainer>

          {isContentEnabled && (
            <>
              <PerformanceKpiSection
                mainCardsData={mainCardsData}
                loading={pageData.loading}
                error={pageData.error}
                onCardClick={onSparklineCardClick}
              />

              <HowWeDoIt
                isDesktopLarge={isDesktopLarge}
                loading={pageData.loading}
                error={pageData.error}
                resourceAllocationCardsData={resourceAllocationCardsData}
                onResourceAllocationCardClick={onResourceAllocationCardClick}
              />
            </>
          )}

          <PillarResources
            pillar={formatMessage({
              id: 'Pillars.pageName.connectionsCreativity',
            })}
          />
        </StyledHomeContainer>
      </StyledGridContainer>
    </>
  );
};
